-- ============================================================
-- Periodization expansion: DUP + Conjugate/Block programs for
-- Golf, Swim/Water Polo, and Track divisions (2 new per division).
-- Models: daily undulating (DUP), conjugate (Westside-adapted),
-- and block periodization (Issurin) per NSCA Essentials of S&C.
-- Deterministic uuid5 ids - safe to re-run (inserts only).
-- ============================================================

-- Column guards (no-ops when already present)
alter table programs add column if not exists type text;
alter table programs add column if not exists level text;
alter table programs add column if not exists week_notes jsonb default '{}'::jsonb;
alter table exercises add column if not exists pattern text;
alter table exercises add column if not exists equipment text;
alter table exercises add column if not exists alt text;
alter table exercises add column if not exists rest text;
alter table exercises add column if not exists progressions jsonb default '{}'::jsonb;




