insert into clients (id, name, goal, notes) values ('160a18de-b515-5ebd-945c-49f722d8a30e', '🏃 Track Templates', 'Program templates', 'Sprint/track & field templates — duplicate to a real client, then adjust.') on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('98a1ea28-924b-55bd-9136-0128516eae77', '280b37a6-9770-5ca2-8eae-b36ddf570366', 'Golf · DUP Undulating (12wk)', 'Power', 'Intermediate', 12, '{"1": "Daily Undulating Periodization: Day 1 heavy strength, Day 2 speed/power (club-speed work), Day 3 volume. Research (Rhea et al. 2002; Zourdos et al. 2016) supports daily variation for trained athletes. TPI mobility drills in every warm-up.", "4": "Deload week \u2014 drop to 2 sets, keep bar speed crisp.", "8": "Deload week.", "12": "Taper & test: re-test club speed and tested maxes."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('d44939d5-6618-5c94-b992-08cc89599639', '280b37a6-9770-5ca2-8eae-b36ddf570366', 'Golf · Conjugate Speed-Strength (8wk)', 'Power', 'Advanced', 8, '{"1": "Conjugate method adapted for the rotational athlete (Westside-informed): rotate the max-effort lift every 2 weeks, train speed weekly at max intent, build volume with repetition work. Wks 1-2 ME lift = Trap-Bar Deadlift.", "3": "ME lift rotates: Front Squat (heavy 3).", "4": "Light week \u2014 trim a set everywhere, keep intent.", "5": "ME lift rotates: Romanian Deadlift (heavy 3).", "7": "ME lift returns to Trap-Bar Deadlift \u2014 beat your week-2 number.", "8": "Test week: heavy single-ish (RPE 9) + club-speed re-test."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('74bf834f-770b-5048-ad28-843d1b775c55', '439ad9b5-c69f-5118-881a-a55d1c3ee596', 'Swim/WP · In-Season DUP (8wk)', 'Strength', 'Intermediate', 8, '{"1": "In-season undulating: lifting supports the pool, never competes with it. Day 1 heavy/low-volume, Day 2 explosive, Day 3 prehab-pump (optional \u2014 skip on 3-game weeks). Cap everything at RPE 8.", "4": "Deload \u2014 2 sets across the board.", "7": "Championship taper: cut a set, keep speed.", "8": "Taper \u2014 movement quality only."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('3e8766a9-4800-5c8f-8bb5-326c8d92e45a', '439ad9b5-c69f-5118-881a-a55d1c3ee596', 'Swim/WP · Conjugate Off-Season (12wk)', 'Power', 'Advanced', 12, '{"1": "Conjugate concurrent block: ME upper (pull bias, lift rotates every 2 wks \u2014 wks 1-2 Weighted Pull-Up), DE lower + throws, repetition volume 2:1 pull:push, strength lower. Cuff work micro-dosed all block.", "3": "ME lift rotates: Pendlay/Bent-Over Row (heavy 4).", "4": "Deload week.", "5": "ME lift rotates: Incline DB Press (heavy 5).", "7": "ME lift rotates: Weighted Pull-Up \u2014 beat week 2.", "8": "Deload week.", "9": "ME lift free choice \u2014 strongest pull variation.", "12": "Test week: heavy pull-up, jump, and throw numbers."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('36ddb15d-157a-5f4f-a3ea-b7a8ac9b7438', '160a18de-b515-5ebd-945c-49f722d8a30e', 'Track · Block Periodization Sprint (12wk)', 'Power', 'Intermediate', 12, '{"1": "Block periodization (Issurin; Painter et al. 2012, collegiate track): MC1 (wks 1-4) accumulation \u2014 work capacity, tissue prep, sprint mechanics. Sprint work FIRST when fresh, lift after.", "4": "Deload week.", "5": "MC2 (wks 5-8): transmutation \u2014 max strength & speed-strength.", "8": "Deload week.", "9": "MC3 (wks 9-12): realization \u2014 peak power & max velocity. Volume drops, intent maxes.", "12": "Taper / meet week \u2014 short, sharp, fully recovered."}'::jsonb) on conflict (id) do nothing;
insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('8d1cc86e-023e-52dd-bb87-5e3947733672', '160a18de-b515-5ebd-945c-49f722d8a30e', 'Track · In-Season DUP (8wk)', 'Power', 'Intermediate', 8, '{"1": "In-season undulating for sprinters: Day 1 heavy low-dose, Day 2 CNS power (48h+ before meets), Day 3 tempo recovery. Lifting keeps qualities topped up \u2014 the track is the priority.", "4": "Deload week.", "7": "Championship taper begins \u2014 cut sets, keep intent.", "8": "Meet week \u2014 short and sharp only."}'::jsonb) on conflict (id) do nothing;
